select *
from batch.alert_event
where tenant_id = #{tenantId}

    and severity = #{severity}


    and status = #{status}


    and alert_type = #{alertType}

order by last_seen_at desc
limit #{limit}

select *
from batch.alert_event
where status = #{status}
  and escalation_tier < #{maxTier}
  and last_seen_at < current_timestamp
      - make_interval(mins => #{slaMinutes} * (escalation_tier + 1))
order by last_seen_at asc
limit #{limit}

select *
from batch.alert_event
where status = #{status}
order by last_seen_at desc
limit #{limit}

mapper.update:
update batch.alert_event
set escalation_tier = escalation_tier + 1,
    escalated_at = current_timestamp,
    updated_at = current_timestamp
where id = #{id}
  and tenant_id = #{tenantId}
  and status = #{expectedStatus}
  and escalation_tier = #{expectedTier}
